CREATE TABLE demo_dw.`dwd_dist_proxy_order_detail_di` (
  `proxy_ord_detail_id` BIGINT COMMENT '推广订单明细ID（自然键 = b_share_order_detail.id）',
  `pmt_id` BIGINT COMMENT '推广者ID（关联推广者维度）',
  `pmt_nm` STRING COMMENT '推广者姓名（冗余自dim_usr_info_df）',
  `pmt_nick` STRING COMMENT '推广者昵称（冗余自dim_usr_info_df）',
  `pmt_email` STRING COMMENT '推广者邮箱（冗余自dim_usr_info_df）',
  `pmt_lvl_nm` STRING COMMENT '推广者会员等级（冗余自dim_usr_info_df）',
  `pmt_crt_time` DATETIME COMMENT '推广者注册时间（冗余自dim_usr_info_df）',
  `usr_id` BIGINT COMMENT '注册用户ID（关联用户维度）',
  `usr_nm` STRING COMMENT '注册用户姓名（冗余自dim_usr_info_df）',
  `usr_nick` STRING COMMENT '注册用户昵称（冗余自dim_usr_info_df）',
  `email` STRING COMMENT '用户邮箱',
  `usr_cntry_cd` STRING COMMENT '注册用户国家（冗余自dim_usr_info_df）',
  `usr_crt_time` DATETIME COMMENT '注册用户注册时间（冗余自dim_usr_info_df）',
  `ord_id` BIGINT COMMENT '订单ID',
  `pkg_no` STRING COMMENT '包裹号',
  `out_ord_id` STRING COMMENT '三方订单ID',
  `out_ord_no` STRING COMMENT '三方订单号',
  `chnl` STRING COMMENT '订单渠道',
  `out_shop_id` STRING COMMENT '三方店铺ID',
  `out_shop_nm` STRING COMMENT '三方店铺名称',
  `out_ccy` STRING COMMENT '三方币种（来自order_outer）',
  `out_ord_amt` DECIMAL(18,4) COMMENT '三方订单总金额（来自order_outer.outer_order_amount）',
  `out_ord_rmk` STRING COMMENT '海外用户备注（来自order_outer.outer_comment）',
  `out_ord_crt_time` DATETIME COMMENT '外部订单创建时间（来自order_outer.outer_create_time）',
  `out_ord_upd_time` DATETIME COMMENT '外部订单更新时间（来自order_outer.outer_update_time）',
  `cntry` STRING COMMENT '收货国家（来自draft_order）',
  `ord_type_cd` BIGINT COMMENT '订单类型枚举: 1-代发, 2-直购备货, 3-直购直发, 4-询盘备货, 5-询盘直发',
  `ord_stat` BIGINT COMMENT '订单状态: 1-待处理, 2-待支付, 3-备货中, 4-待发货, 5-待送达, 6-已完结, 9-已取消, 10-已退款, 11-已失效',
  `ord_amt` DECIMAL(18,4) COMMENT '三方订单总金额',
  `pur_amt` DECIMAL(18,4) COMMENT '订单采购金额',
  `exprs_no` STRING COMMENT '运单号',
  `biz_no` STRING COMMENT '包裹支付业务单号',
  `line_id` BIGINT COMMENT '物流线路ID',
  `line_nm` STRING COMMENT '物流线路名称',
  `logis_nm` STRING COMMENT '物流公司名称',
  `pkg_wt` DECIMAL(18,6) COMMENT '包裹预估重量',
  `pkg_wt_actl` DECIMAL(18,6) COMMENT '包裹实际重量',
  `pkg_amt_pre` DECIMAL(18,4) COMMENT '包裹预估总费用',
  `pkg_amt_actl` DECIMAL(18,4) COMMENT '包裹实际总费用',
  `pkg_xtra_amt` DECIMAL(18,4) COMMENT '包裹待补款金额',
  `pkg_xtra_paid_amt` DECIMAL(18,4) COMMENT '包裹已补款金额',
  `pkg_ref_amt` DECIMAL(18,4) COMMENT '包裹已退款金额',
  `logis_stat` BIGINT COMMENT '物流状态: 1-在途中, 2-到达待取, 3-派送中, 4-妥投',
  `logis_abn_stat` BIGINT COMMENT '物流异常状态',
  `out_flfl_id` STRING COMMENT '外部履约ID',
  `pay_amt` DECIMAL(18,4) COMMENT '订单支付金额',
  `ref_amt` DECIMAL(18,4) COMMENT '订单退款金额',
  `xtra_amt` DECIMAL(18,4) COMMENT '订单补款金额',
  `actl_amt` DECIMAL(18,4) COMMENT '订单实际金额(支付-退款)',
  `cmsn_amt` DECIMAL(18,4) COMMENT '佣金金额',
  `cmsn_rate` DECIMAL(18,6) COMMENT '佣金比例',
  `pay_time` DATETIME COMMENT '订单支付时间',
  `dly_time` DATETIME COMMENT '订单妥投时间',
  `crt_time` DATETIME COMMENT '佣金记录创建时间'
)
COMMENT '推广订单佣金明细事务事实表-日增量(冗余推广者/注册用户维度)'
PARTITIONED BY (
  `ds` STRING NOT NULL COMMENT '分区日期 yyyyMMdd（佣金记录创建日期）'
)
STORED AS AliOrc
LIFECYCLE 36500;
